import java.util.Scanner;

public class Main {
    static class Tugun {
        int kalit;
        Tugun chap, ong;
        Tugun(int kalit) { this.kalit = kalit; }
    }

    static Tugun qosh(Tugun ildiz, int kalit) {
        Tugun yangi = new Tugun(kalit);
        if (ildiz == null) return yangi;
        Tugun joriy = ildiz;
        while (true) {
            if (kalit < joriy.kalit) {
                if (joriy.chap == null) {
                    joriy.chap = yangi;
                    return ildiz;
                }
                joriy = joriy.chap;
            } else {
                if (joriy.ong == null) {
                    joriy.ong = yangi;
                    return ildiz;
                }
                joriy = joriy.ong;
            }
        }
    }

    static int qadamlar(Tugun ildiz, int x) {
        int son = 0;
        Tugun joriy = ildiz;
        while (joriy != null) {
            son++;
            if (x == joriy.kalit) return son;
            joriy = x < joriy.kalit ? joriy.chap : joriy.ong;
        }
        return son;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Tugun ildiz = null;
        for (int i = 0; i < n; i++) ildiz = qosh(ildiz, in.nextInt());
        int q = in.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            if (k > 0) sb.append(' ');
            sb.append(qadamlar(ildiz, in.nextInt()));
        }
        System.out.println(sb);
    }
}

