#include <iostream>
using namespace std;

struct Tugun {
    int kalit;
    Tugun* chap = nullptr;
    Tugun* ong = nullptr;
};

Tugun* qosh(Tugun* ildiz, int kalit) {
    Tugun* yangi = new Tugun{kalit};
    if (ildiz == nullptr) return yangi;
    Tugun* joriy = ildiz;
    while (true) {
        Tugun*& keyingi = kalit < joriy->kalit ? joriy->chap : joriy->ong;
        if (keyingi == nullptr) {
            keyingi = yangi;
            return ildiz;
        }
        joriy = keyingi;
    }
}

int qadamlar(Tugun* ildiz, int x) {
    int son = 0;
    Tugun* joriy = ildiz;
    while (joriy != nullptr) {
        son++;
        if (x == joriy->kalit) return son;
        joriy = x < joriy->kalit ? joriy->chap : joriy->ong;
    }
    return son;
}

int main() {
    int n;
    cin >> n;
    Tugun* ildiz = nullptr;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        ildiz = qosh(ildiz, x);
    }
    int q;
    cin >> q;
    for (int k = 0; k < q; k++) {
        int x;
        cin >> x;
        cout << qadamlar(ildiz, x) << (k + 1 == q ? "\n" : " ");
    }
    return 0;
}
